ROLE_MAP = {"LA": "LA", "SUPP": "SUPP", "DM": "DM"}


class Command(BaseCommand):
    help = "Carga acciones clave de servicios D.sign desde el Excel maestro."

    def handle(self, *args, **options):
        from apps.accounts.models import Role
        from apps.services.models import Deliverable, KeyActivity, ServiceActivity, ServiceTemplate

        roles = {r.code: r for r in Role.objects.all()}
        created_count = 0
        skipped_count = 0
        order_tracker = {}

        for code, deliverable_name, activity_name, action_name, role_code, hours in DATA:
            deliverable_name = " ".join(deliverable_name.split())
            activity_name = " ".join(activity_name.split())
            action_name = " ".join(action_name.split())

            try:
                service = ServiceTemplate.objects.get(code=code)
            except ServiceTemplate.DoesNotExist:
                skipped_count += 1
                continue

            key_activity = None
            if deliverable_name and activity_name:
                try:
                    deliverable = service.deliverables.get(name=deliverable_name)
                    key_activity = deliverable.key_activities.get(name=activity_name)
                except (Deliverable.DoesNotExist, KeyActivity.DoesNotExist):
                    pass

            role = roles.get(ROLE_MAP.get(role_code, ""))
            tracker_key = (code, deliverable_name, activity_name)
            order_tracker[tracker_key] = order_tracker.get(tracker_key, 0) + 1
            order = order_tracker[tracker_key]

            _, created = ServiceActivity.objects.get_or_create(
                service_template=service,
                key_activity=key_activity,
                name=action_name,
                defaults={
                    "responsible_role": role,
                    "estimated_hours": hours,
                    "order": order,
                },
            )
            if created:
                created_count += 1

        self.stdout.write(
            self.style.SUCCESS(
                f"✓ Acciones: {created_count} creadas, {skipped_count} omitidas."
            )
        )
